import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import 'bootstrap/dist/css/bootstrap.css';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';
import './navbar.css';

function Navbar() {
  const navigate = useNavigate();

  function handleNav(path) {
    navigate(path);
    // 導航後關閉手機版選單
    const navbarCollapse = document.getElementById('navbarNavContent');
    if (navbarCollapse && navbarCollapse.classList.contains('show')) {
      const bsCollapse = new window.bootstrap.Collapse(navbarCollapse);
      bsCollapse.hide();
    }
  }

  // 確保 Bootstrap JavaScript 正確載入
  useEffect(() => {
    // 點擊外部區域時關閉下拉選單
    const handleClickOutside = (event) => {
      const navbarCollapse = document.getElementById('navbarNavContent');
      const navbarToggler = document.querySelector('.navbar-toggler');
      
      if (navbarCollapse && 
          navbarCollapse.classList.contains('show') && 
          !navbarCollapse.contains(event.target) && 
          !navbarToggler.contains(event.target)) {
        const bsCollapse = new window.bootstrap.Collapse(navbarCollapse);
        bsCollapse.hide();
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => {
      document.removeEventListener('click', handleClickOutside);
    };
  }, []);

  return (
    <nav className="navbar navbar-expand-lg bg-custom fixed-top">
      <div className="container-fluid">
        
        <a className="navbar-brand" href="#" onClick={(e) => {e.preventDefault(); handleNav("/");}}>
          <img 
            src={`${process.env.PUBLIC_URL}/logoc.png`} 
            alt="AI Prompt Guide Logo"
          />
        </a>

        <button
          className="navbar-toggler"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#navbarNavContent"
          aria-controls="navbarNavContent"
          aria-expanded="false"
          aria-label="Toggle navigation"
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className="collapse navbar-collapse" id="navbarNavContent">
          <ul className="navbar-nav ms-auto">
            <li className="nav-item">
              <a className="nav-link" href="#" onClick={(e) => {e.preventDefault(); handleNav("/");}}>
                首頁
              </a>
            </li>
            <li className="nav-item dropdown">
              <a 
                className="nav-link dropdown-toggle" 
                href="#" 
                role="button" 
                data-bs-toggle="dropdown" 
                aria-expanded="false"
              >
                線性迴歸
              </a>
              <ul className="dropdown-menu">
                <li><a className="dropdown-item" href="#" onClick={(e) => {e.preventDefault(); handleNav("/lr_practice");}}>學習單</a></li>
                <li><a className="dropdown-item" href="#" onClick={(e) => {e.preventDefault(); handleNav("/lr_1");}}>colab實作</a></li>
                <li><a className="dropdown-item" href="#" onClick={(e) => {e.preventDefault(); handleNav("/lr_2");}}>網頁設計實作</a></li>
              </ul>
            </li>
            <li className="nav-item dropdown">
              <a 
                className="nav-link dropdown-toggle" 
                href="#" 
                role="button" 
                data-bs-toggle="dropdown" 
                aria-expanded="false"
              >
                K-means
              </a>
              <ul className="dropdown-menu">
                <li><a className="dropdown-item" href="#" onClick={(e) => {e.preventDefault(); handleNav("/project1/k-means");}}>學習單</a></li>
                <li><a className="dropdown-item" href="#" onClick={(e) => {e.preventDefault(); handleNav("/project1/k-means");}}>colab實作</a></li>
                <li><a className="dropdown-item" href="#" onClick={(e) => {e.preventDefault(); handleNav("/project1/k-means");}}>網頁設計實作</a></li>
              </ul>
            </li>
          </ul>
          &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
        </div>
        
      </div>
    </nav>
  );
}

export default Navbar;